// Directories this suite deletes/replaces are validated FIRST. A directory is deletable only if it is absolute, deep enough, not the filesystem root,
// not the home directory, not the working directory, not equal to / containing / inside the project, tests, fixtures or results file, not a symlink,
// and either absent, empty, or carrying this suite's ownership marker. Previous evidence is moved aside, never deleted.
const MARK = '.plainsong-3a-owned';
function assertOwnable(dir, label, protect, ancestors = ANCESTORS) {
  const d = path.resolve(dir), depth = d.split(path.sep).filter(Boolean).length;
  if (d === path.parse(d).root || depth < 3) throw new Error(`${label} refused: ${d} is too shallow to be a generated directory`);
  let st = null; try { st = fs.lstatSync(d); } catch (e) { /* absent: fine */ }      // lstat: a dangling symlink must not look like "absent"
  if (st && (st.isSymbolicLink() || !st.isDirectory())) throw new Error(`${label} refused: ${d} is a symlink or not a directory`);
  // check the lexical path AND the real path of its parent (a symlinked parent could redirect the deletion)
  let realParent; try { realParent = fs.realpathSync(path.dirname(d)); } catch (e) { realParent = path.dirname(d); }
  for (const cand of new Set([d, path.join(realParent, path.basename(d))])) {
    for (const q0 of protect) for (const q of new Set([path.resolve(q0), (() => { try { return fs.realpathSync(q0); } catch (e) { return path.resolve(q0); } })()])) if (cand === q || q.startsWith(cand + path.sep) || cand.startsWith(q + path.sep)) throw new Error(`${label} refused: ${cand} overlaps protected path ${q}`);
    for (const q0 of ancestors) for (const q of new Set([path.resolve(q0), (() => { try { return fs.realpathSync(q0); } catch (e) { return path.resolve(q0); } })()])) if (cand === q || q.startsWith(cand + path.sep)) throw new Error(`${label} refused: ${cand} is, or contains, protected location ${q}`);
  }
  if (st) { const ents = fs.readdirSync(d); if (ents.length && !ents.includes(MARK)) throw new Error(`${label} refused: ${d} is not empty and is not owned by this suite (no ${MARK})`); }
  return d;
}
const PROTECT = [path.dirname(HERE), HERE, FIX, path.resolve(FX), OUT, process.cwd()];   // generated dirs may not overlap these either way
const ANCESTORS = [require('os').homedir(), '/home', '/tmp', '/mnt', '/opt', '/usr', '/etc', '/var'];   // ...nor be, or contain, these
assertOwnable(WORK, 'WORK', PROTECT); assertOwnable(EVD, 'evidence dir', [], PROTECT.concat(ANCESTORS));   // inside the project's tests folder is fine, but it may not BE or CONTAIN any protected path
