// ---------- credentials used as sentinels: they must never appear in any export ----------
const SEC = { src1: 'S-SRC-SECRET-7f3a91c0', src2: 'S-SRC-OTHER-5c22d04e', tgt1: 'S-TGT-SECRET-1b8e44a7', tgt2: 'S-TGT2-SECRET-90ac1763', p2: 'S-P2-SECRET-3d6f08b2' };
const FORBID = Object.values(SEC);
const secObj = (o) => Object.entries(o).map(([key, value]) => ({ key, value: { token: value } })).sort((a, b) => (a.key < b.key ? -1 : 1));   // seeded as { token: <sentinel> }

// ---------- independent oracle wrappers ----------
// The oracle's output file is removed first (it is always inside WORK), the process outcome is checked, and the report is validated before use:
// exit 0 is accepted only for a complete report with fail == 0; exit 1 only for a complete report with fail > 0 (negative controls); anything else throws.
function runOracle(args, outPath, okStatuses, o = {}) {   // o.oracle / o.timeout exist ONLY so the harness controls can run a fake oracle
  if (!outPath.startsWith(WORK + path.sep)) throw new Error('oracle output outside WORK: ' + outPath);
  fs.rmSync(outPath, { force: true });
  const r = spawnSync('python3', ['-I', o.oracle || ORACLE, ...args], { encoding: 'utf-8', maxBuffer: 1 << 28, timeout: o.timeout || 180000 });
  if (r.error || r.signal || r.status === null) throw new Error('oracle did not finish: ' + (r.error ? r.error.message : r.signal));
  if (!okStatuses.includes(r.status)) throw new Error(`oracle exit ${r.status}: ${(r.stderr || '').slice(0, 400)}`);
  if (!fs.existsSync(outPath)) throw new Error('oracle produced no report');
  return { r, rep: JSON.parse(fs.readFileSync(outPath, 'utf-8')) };
}
function truthOf(zip) {
  const out = path.join(WORK, 'truth', path.basename(zip).replace(/\.zip$/, '.truth.json'));
  const { rep } = runOracle(['truth', zip, out, '--forbid', ...FORBID], out, [0]);
  if (rep.schema !== 'oracle_2c.truth.v1' || rep.file !== zip || !Array.isArray(rep.tracks) || !Array.isArray(rep.entries) || !Array.isArray(rep.selfcheck)) throw new Error('truth report has the wrong schema or is for another file');
  return rep;
}
const STATUSES = ['exact', 'allowed', 'FAIL'];
function compareZ(a, b, tag, o = {}) {
  const out = path.join(WORK, 'compare', tag.replace(/[^a-z0-9_-]+/gi, '_') + '.compare.json');
  const args = ['compare', a, b, out]; if (o.theme !== undefined) args.push('--b-theme', o.theme || 'none'); if (o.secrets) args.push('--b-secret-keys', o.secrets.join('|')); if (o.timeUnavailable) args.push('--time-unavailable');
  const { r, rep } = runOracle(args, out, [0, 1]);
  const n = s => rep.results.filter(x => x.status === s).length;
  if (rep.schema !== 'oracle_2c.compare.v1' || rep.A !== a || rep.B !== b || !Array.isArray(rep.results) || !rep.results.length || rep.results.some(x => typeof x.check !== 'string' || !STATUSES.includes(x.status))) throw new Error('compare report has the wrong schema, files or entries');
  if (rep.fail !== n('FAIL') || rep.allowed !== n('allowed') || rep.exact !== n('exact') || rep.fail + rep.allowed + rep.exact !== rep.results.length) throw new Error('compare report counts are inconsistent');
  if ((r.status === 0) !== (rep.fail === 0)) throw new Error(`oracle exit ${r.status} contradicts its report (fail=${rep.fail})`);
  return rep;
}
// one record per compare + the load-bearing categories individually, + every allowed difference spelled out
function recCompare(tag, rep) {
  const by = p => rep.results.filter(x => x.check.startsWith(p));
  const st = p => { const r = by(p); return r.length && r.every(x => x.status === 'exact'); };
  const allowed = rep.results.filter(x => x.status === 'allowed').map(x => x.check + ' [' + x.detail + ']');
  rec(`${tag}: oracle comparison has ZERO failures (${rep.exact} exact, ${rep.allowed} allowed, ${rep.fail} failed)`, rep.fail === 0, rep.results.filter(x => x.status === 'FAIL').map(x => x.check + ' :: ' + x.detail).join(' || '));
  rec(`${tag}: tracks records identical (order and key order), playlists identical`, st('tracks records') && st('playlists records'), J(by('tracks records').concat(by('playlists records')).map(x => x.status)));
  rec(`${tag}: every audio entry identical in order: key, MIME, size, SHA-256`, st('audio list') && by('blobs/').every(x => x.status === 'exact'), J(by('audio list').map(x => x.detail)));
  rec(`${tag}: kv keys identical${rep.results.some(x => x.check.startsWith('kv[session]') && x.status === 'allowed') ? ' (session differs ONLY in the allowed time field, see below)' : ''}`, by('kv').every(x => x.status !== 'FAIL'));
  if (allowed.length) rec(`${tag}: narrowly allowed differences, each with its stated reason (not ignored fields): ${allowed.length}`, true, allowed.join(' | '));
  return rep;
}
function recExport(tag, t) {
  rec(`${tag}: independent self-check of the export (layout/order, stored, CRC-32 vs ZIP header and manifest, sizes, counts) found no problem`, t.selfcheck.length === 0, t.selfcheck.join('; '));
  const hits = Object.entries(t.forbiddenHits).filter(([, h]) => h.raw || Object.keys(h.entries).length);
  rec(`${tag}: no credential value appears anywhere in the export (raw byte scan for ${FORBID.length} sentinels) and no secret: key is in kv.json`, hits.length === 0 && t.secretKeysInKv.length === 0, J(hits) + J(t.secretKeysInKv));
}

// ---------- browser pages ----------
const SPY = () => {
  window.__plays = 0; window.__ls = 0; window.__tw = [];
  const P = HTMLMediaElement.prototype.play; HTMLMediaElement.prototype.play = function () { window.__plays++; return P.apply(this, arguments); };
  window.addEventListener('loadstart', () => { window.__ls++; }, true);   // media events do not bubble; the capture phase on window still sees them
  for (const n of ['put', 'add', 'delete', 'clear']) { const o = IDBObjectStore.prototype[n]; IDBObjectStore.prototype[n] = function (...a) { try { if (this.name === 'tracks') window.__tw.push({ op: n, key: (n === 'put' || n === 'add') ? (a[0] && a[0].id) : a[0] }); } catch (e) { } return o.apply(this, a); }; }   // every write to the tracks store
};
const ALLBLOCKED = [], ALLSCN = []; let CUR = '';
async function newPage(browser, { viewport } = {}) {
  const ctx = await browser.newContext({ viewport: viewport || { width: 1280, height: 800 }, acceptDownloads: true });
  await ctx.addInitScript(SPY);
  const page = await ctx.newPage(); const errs = [];
  page.on('pageerror', e => errs.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error' && !/Failed to load resource|ERR_FAILED|net::/.test(m.text())) errs.push('console: ' + m.text()); });
  await page.route('**/*', r => { const u = r.request().url(); if (u.startsWith(ORIGIN)) return r.continue(); ALLBLOCKED.push(u.slice(0, 160)); ALLSCN.push(CUR); return r.abort(); });
  page.__fc = []; page.on('filechooser', fc => { page.__fc.push(fc); });
  page.__dls = []; page.on('download', d => { page.__dls.push(d); });
  return { ctx, page, errs };
}
// The Home screen fetches public discover lists (Audius/Archive trending) whenever it renders, exactly as on any page load; that is the app's existing
