  if (!fc) throw new Error('no file chooser from the Restore button');
  await fc.setFiles(zip); await waitText(page, 'Restore preview|can’t be restored|isn’t available');
  const preview = await dlgText(page); if (!/Restore preview/.test(preview)) return { preview, text: preview, refused: true };
  await page.click('#dlg [data-bk="go"]'); await waitText(page, 'Replace your library');
